    __shared__ float tile_A[TILE_DIM][TILE_DIM];
    __shared__ float tile_B[TILE_DIM][TILE_DIM];

    int row = blockIdx.y * TILE_DIM + threadIdx.y;
    int col = blockIdx.x * TILE_DIM + threadIdx.x;

    int thread_row = threadIdx.y;
    int thread_col = threadIdx.x;

    float sum = 0.0f;

    for (int tile_k = 0; tile_k < N / TILE_DIM; ++tile_k) {
        // Load tiles into shared memory
        if (row < N && (tile_k * TILE_DIM + thread_col) < N) {
            tile_A[thread_row][thread_col] = A[row * N + (tile_k * TILE_DIM + thread_col)];
        } else {
            tile_A[thread_row][thread_col] = 0.0f;
