import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_DIM 16
#define BLOCK_ROWS 16
#define REG_TILE_SIZE 4

__global__ void matmul_kernel_reg_tiled(const float* A, const float* B, float* C, int N) {
    __shared__ float tile_A[TILE_DIM][TILE_DIM];
    __shared__ float tile_B[TILE_DIM][TILE_DIM];

    int block_row = blockIdx.y;
    int block_col = blockIdx.x;

    int thread_row = threadIdx.y;
    int thread_col = threadIdx.x;

    // 4x4 register tiling
    float reg_C[REG_TILE_SIZE][REG_TILE_SIZE] = {{0.0f}};

    int row = block_row * TILE_DIM + thread_row;
    int col = block_col * TILE_DIM + thread_col;

    for (int tile_k = 0; tile_k < (N + TILE_DIM - 1) / TILE_DIM; ++tile_k) {
        // Load tiles into shared memory
        // Each thread loads 4 elements for A and 4 for B
        for(int i = 0; i < REG_TILE_SIZE; ++i){
            if (block_row * TILE_DIM + thread_row < N && tile_k * TILE_DIM + thread_col + i * (TILE_DIM/REG_TILE_SIZE) < N)
                tile_A[thread_row][thread_col + i * (TILE_DIM/REG_TILE_SIZE)] = A[(block_row * TILE_DIM + thread_row) * N + tile_k * TILE_DIM + thread_col + i * (TILE_DIM/REG_TILE_SIZE)];
            else
                tile_A[thread_row][thread_col + i * (TILE_DIM/REG_TILE_SIZE)] = 0.0;

            if (tile_k * TILE_DIM + thread_row < N && block_col * TILE_DIM + thread_col + i * (TILE_DIM/REG_TILE_SIZE) < N)
                tile_B[thread_row][thread_col + i * (TILE_DIM/REG_TILE_SIZE)] = B[(tile_k * TILE_DIM + thread_row) * N + block_col * TILE_DIM + thread_col + i * (TILE_DIM/REG_TILE_SIZE)];
            else
                tile_B[thread_row][thread_col + i * (TILE_DIM/REG_TILE_SIZE)] = 0.0;
        }
        __syncthreads();

        // Compute partial sum from tiles into registers
        for (int k = 0; k < TILE_DIM; ++k) {
            for (int i = 0; i < REG_TILE_SIZE; i++) {
                for (int j = 0; j < REG_TILE_SIZE; j++) {
                     reg_C[i][j] += tile_A[thread_row + i * (BLOCK_ROWS/REG_TILE_SIZE)][k] * tile_B[k][thread_col + j * (TILE_DIM/REG_TILE_SIZE)];
                }
            }
        }
        __syncthreads();
    }

    // Write results from registers to global memory
    for (int i = 0; i < REG_TILE_SIZE; i++) {
        for (int j = 0; j < REG_TILE_SIZE; j++) {
            if (block_row * TILE_DIM + thread_row + i * (BLOCK_ROWS/REG_TILE_SIZE) < N && block_col * TILE_DIM + thread_col + j * (TILE_DIM/REG_TILE_SIZE) < N) {
                C[(block_row * TILE_DIM + thread_row + i * (BLOCK_ROWS/REG_TILE_SIZE)) * N + block_col * TILE_DIM + thread_col + j * (TILE_DIM/REG_TILE_SIZE)] = reg_C[i][j];
            }
        }
    }
}


torch::Tensor matmul_cuda(torch::Tensor A, torch.Tensor B) {
    TORCH_CHECK(A.dim() == 2, "A must be a 2D tensor");
    TORCH_CHECK(B.dim() == 2, "B must be a 2D tensor");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions are not compatible for multiplication");

    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    const dim3 blockSize(TILE_DIM / REG_TILE_SIZE, TILE_DIM / REG_TILE_SIZE);
    const dim3 gridSize((N + TILE_DIM - 1) / TILE_DIM, (N + TILE_DIM - 1) / TILE_DIM);

    matmul_kernel_reg_tiled<<<gridSize, blockSize>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

